'use strict';

import {
  atob,
  binaryStringToBlobOrBuffer as binStringToBlobOrBuffer,
  blobOrBufferToBase64 as blufferToBase64,
} from 'pouchdb-binary-utils';

import { createError, BAD_ARG } from 'pouchdb-errors';
import { binaryMd5 as md5 } from 'pouchdb-md5';

// Convert an attachment supplied by the user into the format this adapter
// stores: a blob or base64 string, with digest and length filled in. Stub
// attachments are passed through untouched; the caller resolves them against
// the attachments already stored for the document.
export default function preProcessAttachment(attachment, attachmentFormat) {
  if (attachment.stub) {
    return Promise.resolve(attachment);
  }

  let binData;
  if (typeof attachment.data === 'string') {
    try {
      binData = atob(attachment.data);
    } catch (e) {
      return Promise.reject(createError(BAD_ARG, 'Attachment is not a valid base64 string'));
    }
    if (attachmentFormat === 'binary') {
      attachment.data = binStringToBlobOrBuffer(binData, attachment.content_type);
    }
  } else {
    binData = attachment.data;
    if (attachmentFormat === 'base64') {
      // TODO could run these in parallel, if we cared
      return new Promise(resolve => {
        blufferToBase64(attachment.data, function (b64) {
          attachment.data = b64;
          md5(binData, function (result) {
            attachment.digest = 'md5-' + result;
            attachment.length = binData.size || binData.length || 0;
            resolve(attachment);
          });
        });
      });
    }
  }

  return new Promise(function (resolve) {
    md5(binData, function (result) {
      attachment.digest = 'md5-' + result;
      attachment.length = binData.size || binData.length || 0;
      resolve(attachment);
    });
  });
}
